        "field": "action.post_action",
        "max_depth": 1,
        "create_rerun_kind": "rerun_workflow",
        "create_rerun_action_kinds": [
          "retrieve_reference"
        ],
        "review_required_input": "complete_updated_file",
        "ask_user_post_action": null
