{
  "contract_version": "salt_create_catalog_v1",
  "query": "Button",
  "status": "resolved",
  "matches": [
    {
      "id": "component.button",
      "entity_type": "component",
      "name": "Button",
      "aliases": [
        "Action",
        "UI action"
      ],
      "route_slugs": [],
      "package": "@salt-ds/core",
      "status": "stable",
      "categories": [
        "actions"
      ],
      "summary": "Button is an interactive component that allows the user to execute an action. Button comes in three distinct appearances: solid, bordered, and transparent. These styles provide greater choice and flexibility for establishing hierarchy and affordance within a UI. You can display a button with or without a text description or icon.",
      "when_to_use": [
        "To allow the user to execute an action, such as “submit”, “merge” or “upload”. Buttons are typically placed in components and contexts such as dialogs, cards and forms."
      ],
      "when_not_to_use": [
        "When the primary action is to take the user to another page or window rather than to trigger a function. Instead, use Link."
      ],
      "starter_available": true,
      "supporting_surfaces": [
        "Button bar",
        "Split button"
      ],
      "related_entities": [
        "Button bar",
        "Split button"
      ],
      "retrieval_signals": {
        "contrast_targets": [
          {
            "target": "Link",
            "relation": "prefer-instead",
            "evidence": [
              "When the primary action is to take the user to another page or window rather than to trigger a function. Instead, use Link."
            ]
          }
        ]
      },
      "example_count": 10,
      "source_urls": [
        "/salt/components/button",
        "/salt/components/button/accessibility",
        "/salt/components/button/examples",
        "/salt/components/button/usage"
      ]
    }
  ]
}

